function M.setup(opts)
  current = vim.tbl_deep_extend("force", defaults, opts or {})
end

function M.get()
  return current
end

local function visible_range()
  return vim.fn.line("w0"), vim.fn.line("w$")
end

function M.label(scope)
  if scope.kind == "path" then
    return "path:" .. (scope.path or "?")
  elseif scope.kind == "selection" or scope.kind == "visible" then
    local r = scope.range or { s = 0, e = 0 }
    return ("%s:%d-%d"):format(scope.kind, r.s, r.e)
  end
  return scope.kind
end

local function buf_valid(bufnr)
  return type(bufnr) == "number" and api.nvim_buf_is_valid(bufnr)
end

function M.goto_next(count)
  diag_jump(count or 1)
end

function M.goto_prev(count)
  diag_jump(-(count or 1))
end

local function editable(bufnr)
  return type(bufnr) == "number" and api.nvim_buf_is_valid(bufnr) and api.nvim_buf_is_loaded(bufnr)
end

function M.set(bufnr, issues)
  if not api.nvim_buf_is_valid(bufnr) then
    return
  end
  store[bufnr] = { tick = api.nvim_buf_get_changedtick(bufnr), issues = issues }
end

function M.invalidate(bufnr)
  store[bufnr] = nil
end

local function cancel_key_for(scope)
  if scope.kind == "cwd" or scope.kind == "path" then
    return "wide:" .. (scope.path or "cwd")
  end
  return "buf:" .. tostring(scope.bufnr or 0)
end

function M.scan(scope, cfg)
  if is_single_buffer(scope) then
    return post(raw_buffer(scope, cfg), cfg)
  end
  return post(native.scan_scope(scope, cfg), cfg)
end

function M.has(word)
  return ensure_loaded()[word] == true
end

function M.available()
  return fn.executable("codespell") == 1
end

function M.scan_async(scope, _cfg, cb)
  if not M.available() then
    cb({})
    return nil
  end

  local skip = { "--skip=.git,node_modules,.venv,dist,build,target,*.min.*,*.lock" }
  local base, argv
  if scope.kind == "path" and scope.path then
    if fn.isdirectory(scope.path) == 1 then
      base, argv = scope.path, { "codespell", "." }
    else
      base, argv = nil, { "codespell", scope.path }
    end
  else
    base, argv = fn.getcwd(), { "codespell", "." }
  end
  vim.list_extend(argv, skip)

  return job.run(argv, {
    cwd = base,
    timeout_ms = 20000,
    on_done = function(_ok, out, _err)
      cb(M.parse(out or "", base))
    end,
  })
end

function M.available()
  return fn.executable("cspell") == 1
end

function M.scan_async(scope, _cfg, cb)
  if not M.available() then
    cb({})
    return nil
  end

  local flags = { "--no-color", "--no-summary", "--no-progress" }
  local base, argv
  if scope.kind == "path" and scope.path then
    if fn.isdirectory(scope.path) == 1 then
      base, argv = scope.path, { "cspell", "lint", "**" }
    else
      base, argv = nil, { "cspell", "lint", scope.path }
    end
  else
    base, argv = fn.getcwd(), { "cspell", "lint", "**" }
  end
  vim.list_extend(argv, flags)

  return job.run(argv, {
    cwd = base,
    timeout_ms = 30000,
    on_done = function(_ok, out, _err)
      cb(M.parse(out or "", base))
    end,
  })
end

function M.available()
  return fn.executable("node") == 1 and fn.executable("cspell") == 1 and not state.failed
end

function M.suggest(_issue)
  return {}
end

function M.available()
  return type(vim.spell) == "table" and type(vim.spell.check) == "function"
end

function M.suggest(issue)
  if type(issue) ~= "table" or type(issue.word) ~= "string" then
    return {}
  end
  local ok, res = pcall(fn.spellsuggest, issue.word, 10)
  if ok and type(res) == "table" then
    return res
  end
  return {}
end

function M.available()
  return fn.executable("typos") == 1
end

function M.is_absolute(p)
  return p:match("^%a:[/\\]") ~= nil or p:match("^[/\\]") ~= nil
end

function M.resolve_path(path, base)
  if base and not M.is_absolute(path) then
    path = base .. "/" .. path:gsub("^%.[/\\]", "")
  end
  return fn.fnamemodify(path, ":p")
end

function M._items(issue, on_done)
  local function done_msg(ok, err, ok_msg)
    if ok then
      notify.info(ok_msg)
      on_done()
    else
      notify.error(tostring(err))
    end
  end

  local ignore_items = {
    {
      label = "Ignore (session)",
      action = function()
        ignore.add_session(issue.word)
        notify.info(("Ignoring '%s' this session"):format(issue.word))
        on_done()
      end,
    },
    {
      label = "Ignore (persistent)",
      action = function()
        done_msg(
          ignore.add_persistent(issue.word),
          nil,
          ("Ignoring '%s' permanently"):format(issue.word)
        )
      end,
    },
    {
      label = "Jump to location",
      action = function()
        jump_to(issue)
      end,
    },
  }

  ---@type { label: string, action: fun() }[]
  local items

local function trouble_ok()
  return pcall(require, "trouble")
end

function M.open(scope, cfg)
  collect.gather(scope, cfg, function(issues)
    M._render(scope, cfg, issues)
  end)
end

function M.clear()
  list.clear(touched)
  touched = {}
end

function M.run_files(lang, opts)
  require("language.translate.files").run(lang, opts)
end

function M.available(cfg)
  return type(cfg.custom) == "table" and type(cfg.custom.cmd) == "function"
end

function M.available(cfg)
  return vim.fn.executable("curl") == 1 and api_key(cfg) ~= nil
end

function M.available(_cfg)
  return vim.fn.executable("curl") == 1
end

function M.get(name)
  return PROVIDERS[name]
end

function M.available(_cfg)
  return vim.fn.executable("trans") == 1
end

local function hcfg()
  return cfg().history or { enable = false, max = 50, persist = false, file = "" }
end

function M.entries()
  return ensure_loaded()
end

function M.clear()
  ring = {}
  save()
end

local function translate_range(bufnr, s, e)
  choose_target(function(lang)
    require("language.translate").run(lang, {
      output = "replace",
      scope = { kind = "selection", bufnr = bufnr, range = { s = s, e = e } },
    })
  end)
end

local function win_valid(win)
  return win and api.nvim_win_is_valid(win)
end

function M.is_open()
  return win_valid(state.input_win) or win_valid(state.output_win)
end

function M._state()
  return state
end
